/****************************************************************************
 * app/velaguard_app/src/vg_modbus_profile.h
 *
 * Issue #02: one Modbus RTU slave profile (defaults + optional JSON).
 ****************************************************************************/

#ifndef APP_VELAGUARD_APP_SRC_VG_MODBUS_PROFILE_H
#define APP_VELAGUARD_APP_SRC_VG_MODBUS_PROFILE_H

#include <stdbool.h>
#include <stdint.h>

#define VG_MB_MAX_POINTS       3
#define VG_MB_PORT_MAX         32
#define VG_MB_NAME_MAX         24
#define VG_MB_KEY_MAX          16
#define VG_MB_LABEL_MAX        24
#define VG_MB_UNIT_MAX         8
#define VG_MB_DTYPE_MAX        12
#define VG_MB_JSON_PATH        "/data/velaguard/configs/modbus_demo.json"

enum vg_modbus_dtype
{
  VG_MB_DT_UINT16 = 0,
  VG_MB_DT_INT16,
  VG_MB_DT_UINT32,
  VG_MB_DT_INT32
};

struct vg_modbus_reg
{
  char key[VG_MB_KEY_MAX];
  char label[VG_MB_LABEL_MAX];
  uint8_t function_code; /* 3 or 4 */
  uint16_t pdu_addr;     /* 0-based PDU address after conversion */
  enum vg_modbus_dtype dtype;
  float scale;
  float offset;
  char unit[VG_MB_UNIT_MAX];
};

struct vg_modbus_profile
{
  char name[VG_MB_NAME_MAX];
  uint8_t slave_addr;
  char port[VG_MB_PORT_MAX];
  int baudrate;
  char parity; /* 'N', 'E', 'O' */
  int data_bits;
  int stop_bits;
  int de_gpio; /* -1 = no-op DE/RE (auto-DE hardware) */
  uint32_t poll_interval_ms;
  uint8_t n_regs;
  struct vg_modbus_reg regs[VG_MB_MAX_POINTS];
};

/* Load compiled defaults, then optional JSON override. Always leaves a valid profile. */
int vg_modbus_profile_load(void);

const struct vg_modbus_profile *vg_modbus_profile_get(void);

/* Convert handbook-style 4xxxx/3xxxx to PDU address. */
uint16_t vg_modbus_addr_to_pdu(uint8_t function_code, uint32_t addr);

#endif /* APP_VELAGUARD_APP_SRC_VG_MODBUS_PROFILE_H */

/****************************************************************************
 * app/velaguard_app/src/vg_modbus_profile.c
 *
 * Defaults + optional /data/velaguard/configs/modbus_demo.json.
 * Minimal hand parser for the #02 schema (no large JSON dependency).
 ****************************************************************************/

#include <nuttx/config.h>

#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "vg_modbus_profile.h"

static struct vg_modbus_profile g_profile;

uint16_t vg_modbus_addr_to_pdu(uint8_t function_code, uint32_t addr)
{
  if (function_code == 3 && addr >= 40001u)
    {
      return (uint16_t)(addr - 40001u);
    }

  if (function_code == 4 && addr >= 30001u)
    {
      return (uint16_t)(addr - 30001u);
    }

  if (addr > 0xffffu)
    {
      return 0;
    }

  return (uint16_t)addr;
}

static void profile_set_defaults(struct vg_modbus_profile *p)
{
  memset(p, 0, sizeof(*p));
  snprintf(p->name, sizeof(p->name), "demo_sim");
  p->slave_addr = 1;
  snprintf(p->port, sizeof(p->port), "/dev/ttyS0");
  p->baudrate = 9600;
  p->parity = 'N';
  p->data_bits = 8;
  p->stop_bits = 1;
  p->de_gpio = -1;
  p->poll_interval_ms = 1000;
  p->n_regs = 1;

  snprintf(p->regs[0].key, sizeof(p->regs[0].key), "r1");
  snprintf(p->regs[0].label, sizeof(p->regs[0].label), "Reg1");
  p->regs[0].function_code = 3;
  p->regs[0].pdu_addr = 0;
  p->regs[0].dtype = VG_MB_DT_UINT16;
  p->regs[0].scale = 1.0f;
  p->regs[0].offset = 0.0f;
  p->regs[0].unit[0] = '\0';
}

static const char *skip_ws(const char *s)
{
  while (*s && isspace((unsigned char)*s))
    {
      s++;
    }

  return s;
}

/* Find "key" then ':' and return pointer after colon (skipping whitespace). */
static const char *find_key(const char *json, const char *key)
{
  char pat[48];
  const char *p;
  size_t klen = strlen(key);

  if (klen + 3 >= sizeof(pat))
    {
      return NULL;
    }

  snprintf(pat, sizeof(pat), "\"%s\"", key);
  p = strstr(json, pat);
  if (p == NULL)
    {
      return NULL;
    }

  p += strlen(pat);
  p = skip_ws(p);
  if (*p != ':')
    {
      return NULL;
    }

  return skip_ws(p + 1);
}

static bool parse_string(const char *p, char *out, size_t outlen)
{
  size_t i = 0;

  if (p == NULL || *p != '"')
    {
      return false;
    }

  p++;
  while (*p && *p != '"' && i + 1 < outlen)
    {
      if (*p == '\\' && p[1])
        {
          p++;
        }

      out[i++] = *p++;
    }

  out[i] = '\0';
  return true;
}

static bool parse_int(const char *p, long *out)
{
  char *end = NULL;
  long v;

  if (p == NULL)
    {
      return false;
    }

  v = strtol(p, &end, 10);
  if (end == p)
    {
      return false;
    }

  *out = v;
  return true;
}

static bool parse_float(const char *p, float *out)
{
  char *end = NULL;
  float v;

  if (p == NULL)
    {
      return false;
    }

  v = strtof(p, &end);
  if (end == p)
    {
      return false;
    }

  *out = v;
  return true;
}

static enum vg_modbus_dtype parse_dtype(const char *s)
{
  if (s == NULL)
    {
      return VG_MB_DT_UINT16;
    }

  if (strcmp(s, "int16") == 0)
    {
      return VG_MB_DT_INT16;
    }

  if (strcmp(s, "uint32") == 0)
    {
      return VG_MB_DT_UINT32;
    }

  if (strcmp(s, "int32") == 0)
    {
      return VG_MB_DT_INT32;
    }

  return VG_MB_DT_UINT16;
}

/* Extract one register object starting at '{' into regs[idx]. Returns next search pos. */
static const char *parse_one_register(const char *obj, struct vg_modbus_reg *reg)
{
  const char *p;
  char tmp[32];
  long n;
  float f;
  uint8_t fc = 3;
  uint32_t raw_addr = 0;

  memset(reg, 0, sizeof(*reg));
  reg->function_code = 3;
  reg->dtype = VG_MB_DT_UINT16;
  reg->scale = 1.0f;
  reg->offset = 0.0f;

  p = find_key(obj, "key");
  if (p && parse_string(p, reg->key, sizeof(reg->key)))
    {
      /* ok */
    }
  else
    {
      snprintf(reg->key, sizeof(reg->key), "r");
    }

  p = find_key(obj, "label");
  if (p && parse_string(p, reg->label, sizeof(reg->label)))
    {
      /* ok */
    }
  else
    {
      snprintf(reg->label, sizeof(reg->label), "%s", reg->key);
    }

  p = find_key(obj, "function_code");
  if (p && parse_int(p, &n) && (n == 3 || n == 4))
    {
      fc = (uint8_t)n;
    }

  reg->function_code = fc;

  p = find_key(obj, "addr");
  if (p && parse_int(p, &n) && n >= 0)
    {
      raw_addr = (uint32_t)n;
    }

  reg->pdu_addr = vg_modbus_addr_to_pdu(fc, raw_addr);

  p = find_key(obj, "data_type");
  if (p && parse_string(p, tmp, sizeof(tmp)))
    {
      reg->dtype = parse_dtype(tmp);
    }

  p = find_key(obj, "scale");
  if (p && parse_float(p, &f))
    {
      reg->scale = f;
    }

  p = find_key(obj, "offset");
  if (p && parse_float(p, &f))
    {
      reg->offset = f;
    }

  p = find_key(obj, "unit");
  if (p)
    {
      parse_string(p, reg->unit, sizeof(reg->unit));
    }

  return obj + 1;
}

static int parse_profile_json(const char *json, struct vg_modbus_profile *out)
{
  const char *p;
  const char *regs;
  char tmp[32];
  long n;
  float f;
  int count = 0;
  const char *cursor;

  profile_set_defaults(out);

  p = find_key(json, "name");
  if (p)
    {
      parse_string(p, out->name, sizeof(out->name));
    }

  p = find_key(json, "slave_addr");
  if (p && parse_int(p, &n) && n >= 1 && n <= 247)
    {
      out->slave_addr = (uint8_t)n;
    }

  p = find_key(json, "poll_interval_ms");
  if (p && parse_int(p, &n) && n >= 200 && n <= 60000)
    {
      out->poll_interval_ms = (uint32_t)n;
    }

  /* serial sub-object keys appear as flat "port"/"baudrate" in file — search whole doc */

  p = find_key(json, "port");
  if (p)
    {
      parse_string(p, out->port, sizeof(out->port));
    }

  p = find_key(json, "baudrate");
  if (p && parse_int(p, &n) && n > 0)
    {
      out->baudrate = (int)n;
    }

  p = find_key(json, "parity");
  if (p && parse_string(p, tmp, sizeof(tmp)) && tmp[0])
    {
      out->parity = (char)toupper((unsigned char)tmp[0]);
      if (out->parity != 'N' && out->parity != 'E' && out->parity != 'O')
        {
          out->parity = 'N';
        }
    }

  p = find_key(json, "data_bits");
  if (p && parse_int(p, &n) && (n == 7 || n == 8))
    {
      out->data_bits = (int)n;
    }

  p = find_key(json, "stop_bits");
  if (p && parse_int(p, &n) && (n == 1 || n == 2))
    {
      out->stop_bits = (int)n;
    }

  p = find_key(json, "de_gpio");
  if (p && parse_int(p, &n))
    {
      out->de_gpio = (int)n;
    }

  regs = find_key(json, "registers");
  if (regs == NULL)
    {
      return 0;
    }

  regs = skip_ws(regs);
  if (*regs != '[')
    {
      return -EINVAL;
    }

  cursor = regs + 1;
  while (count < VG_MB_MAX_POINTS)
    {
      const char *obj = strchr(cursor, '{');
      const char *end;

      if (obj == NULL)
        {
          break;
        }

      end = strchr(obj, '}');
      if (end == NULL)
        {
          break;
        }

      /* parse only this object slice */
      {
        char slice[512];
        size_t len = (size_t)(end - obj + 1);

        if (len >= sizeof(slice))
          {
            len = sizeof(slice) - 1;
          }

        memcpy(slice, obj, len);
        slice[len] = '\0';
        parse_one_register(slice, &out->regs[count]);
        count++;
      }

      cursor = end + 1;
    }

  if (count > 0)
    {
      out->n_regs = (uint8_t)count;
    }

  (void)f;
  return 0;
}

static void log_profile(const struct vg_modbus_profile *p)
{
  uint8_t i;

  printf("[VG][MB] profile name=%s slave=%u port=%s baud=%d %c%d%d "
         "poll=%ums regs=%u de_gpio=%d\n",
         p->name, (unsigned)p->slave_addr, p->port, p->baudrate,
         p->parity, p->data_bits, p->stop_bits,
         (unsigned)p->poll_interval_ms, (unsigned)p->n_regs, p->de_gpio);

  for (i = 0; i < p->n_regs; i++)
    {
      printf("[VG][MB]  reg[%u] key=%s fc=%u pdu=%u scale=%.4f unit=%s\n",
             (unsigned)i, p->regs[i].key,
             (unsigned)p->regs[i].function_code,
             (unsigned)p->regs[i].pdu_addr,
             (double)p->regs[i].scale,
             p->regs[i].unit);
    }
}

int vg_modbus_profile_load(void)
{
  FILE *fp;
  char *buf = NULL;
  long sz;
  size_t nread;
  int ret = 0;

  profile_set_defaults(&g_profile);

  fp = fopen(VG_MB_JSON_PATH, "r");
  if (fp == NULL)
    {
      printf("[VG][MB] No JSON at %s — using defaults\n", VG_MB_JSON_PATH);
      log_profile(&g_profile);
      return 0;
    }

  if (fseek(fp, 0, SEEK_END) != 0)
    {
      fclose(fp);
      printf("[VG][MB] WARNING: JSON seek failed — defaults\n");
      log_profile(&g_profile);
      return 0;
    }

  sz = ftell(fp);
  if (sz <= 0 || sz > 8192)
    {
      fclose(fp);
      printf("[VG][MB] WARNING: JSON size invalid (%ld) — defaults\n", sz);
      log_profile(&g_profile);
      return 0;
    }

  if (fseek(fp, 0, SEEK_SET) != 0)
    {
      fclose(fp);
      log_profile(&g_profile);
      return 0;
    }

  buf = (char *)malloc((size_t)sz + 1);
  if (buf == NULL)
    {
      fclose(fp);
      printf("[VG][MB] WARNING: JSON OOM — defaults\n");
      log_profile(&g_profile);
      return 0;
    }

  nread = fread(buf, 1, (size_t)sz, fp);
  fclose(fp);
  buf[nread] = '\0';

  ret = parse_profile_json(buf, &g_profile);
  free(buf);

  if (ret < 0)
    {
      printf("[VG][MB] WARNING: JSON parse failed (%d) — defaults\n", ret);
      profile_set_defaults(&g_profile);
    }
  else
    {
      printf("[VG][MB] Loaded profile from %s\n", VG_MB_JSON_PATH);
    }

  log_profile(&g_profile);
  return 0;
}

const struct vg_modbus_profile *vg_modbus_profile_get(void)
{
  return &g_profile;
}

/****************************************************************************
 * app/velaguard_app/src/vg_modbus_port.h
 *
 * NuttX serial transport + DE/RE hooks for nanoMODBUS client.
 ****************************************************************************/

#ifndef APP_VELAGUARD_APP_SRC_VG_MODBUS_PORT_H
#define APP_VELAGUARD_APP_SRC_VG_MODBUS_PORT_H

#include <stdbool.h>
#include <stdint.h>

#include "../third_party/nanomodbus/nanomodbus.h"

struct vg_modbus_port
{
  int fd;
  int de_gpio; /* -1 = no-op (auto-DE transceiver) */
  bool open;
};

/* Open/configure serial device. Returns 0 on success, -errno on failure. */
int vg_modbus_port_open(struct vg_modbus_port *port, const char *devpath,
                        int baudrate, char parity, int data_bits,
                        int stop_bits, int de_gpio);

void vg_modbus_port_close(struct vg_modbus_port *port);

/* Fill nmbs platform conf with RTU callbacks; arg = port pointer. */
void vg_modbus_port_fill_platform(struct vg_modbus_port *port,
                                  nmbs_platform_conf *conf);

/* DE/RE helpers (no-op when de_gpio < 0). */
void vg_modbus_port_de_tx(struct vg_modbus_port *port);
void vg_modbus_port_de_rx(struct vg_modbus_port *port);

#endif /* APP_VELAGUARD_APP_SRC_VG_MODBUS_PORT_H */

/****************************************************************************
 * app/velaguard_app/src/vg_modbus_port.c
 *
 * openvela/NuttX serial adapter for nanoMODBUS (client/master only).
 *
 * DE/RE: when de_gpio < 0 (default), this is a documented no-op suitable
 * for auto-direction RS485 modules. Optional GPIO toggle can be wired later.
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <stdio.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>

#include "vg_modbus_port.h"

static speed_t baud_to_flag(int baud)
{
  switch (baud)
    {
      case 1200:
        return B1200;
      case 2400:
        return B2400;
      case 4800:
        return B4800;
      case 9600:
        return B9600;
      case 19200:
        return B19200;
      case 38400:
        return B38400;
      case 57600:
        return B57600;
      case 115200:
        return B115200;
      default:
        return B9600;
    }
}

void vg_modbus_port_de_tx(struct vg_modbus_port *port)
{
  if (port == NULL || port->de_gpio < 0)
    {
      /* No-op: auto-DE transceiver or half-duplex handled in hardware. */
      return;
    }

  /* Optional GPIO DE assert — not configured in #02 default path. */
  (void)port;
}

void vg_modbus_port_de_rx(struct vg_modbus_port *port)
{
  if (port == NULL || port->de_gpio < 0)
    {
      return;
    }

  (void)port;
}

static int32_t port_read(uint8_t *buf, uint16_t count, int32_t byte_timeout_ms,
                         void *arg)
{
  struct vg_modbus_port *port = (struct vg_modbus_port *)arg;
  uint16_t got = 0;

  if (port == NULL || !port->open || port->fd < 0 || buf == NULL)
    {
      return -1;
    }

  while (got < count)
    {
      struct pollfd pfd;
      int pret;
      ssize_t n;
      int to = byte_timeout_ms;

      if (to < 0)
        {
          to = -1;
        }
      else if (to == 0)
        {
          to = 0;
        }

      pfd.fd = port->fd;
      pfd.events = POLLIN;
      pfd.revents = 0;

      pret = poll(&pfd, 1, to);
      if (pret < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -1;
        }

      if (pret == 0)
        {
          /* Timeout: return bytes so far (0..count-1 => nmbs timeout). */
          return (int32_t)got;
        }

      n = read(port->fd, buf + got, (size_t)(count - got));
      if (n < 0)
        {
          if (errno == EINTR || errno == EAGAIN)
            {
              continue;
            }

          return -1;
        }

      if (n == 0)
        {
          return (int32_t)got;
        }

      got += (uint16_t)n;
    }

  return (int32_t)got;
}

static int32_t port_write(const uint8_t *buf, uint16_t count,
                          int32_t byte_timeout_ms, void *arg)
{
  struct vg_modbus_port *port = (struct vg_modbus_port *)arg;
  uint16_t sent = 0;

  (void)byte_timeout_ms;

  if (port == NULL || !port->open || port->fd < 0 || buf == NULL)
    {
      return -1;
    }

  vg_modbus_port_de_tx(port);

  while (sent < count)
    {
      ssize_t n = write(port->fd, buf + sent, (size_t)(count - sent));

      if (n < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          vg_modbus_port_de_rx(port);
          return -1;
        }

      if (n == 0)
        {
          break;
        }

      sent += (uint16_t)n;
    }

  /* Drain TX so DE stays asserted until last bit leaves the wire. */
  (void)tcdrain(port->fd);

  /* Short post-TX silence before RX (RTU turnaround). */
  usleep(2000);
  vg_modbus_port_de_rx(port);

  return (int32_t)sent;
}

int vg_modbus_port_open(struct vg_modbus_port *port, const char *devpath,
                        int baudrate, char parity, int data_bits,
                        int stop_bits, int de_gpio)
{
  struct termios tio;
  int fd;
  int flags;

  if (port == NULL || devpath == NULL)
    {
      return -EINVAL;
    }

  if (port->open && port->fd >= 0)
    {
      vg_modbus_port_close(port);
    }

  memset(port, 0, sizeof(*port));
  port->fd = -1;
  port->de_gpio = de_gpio;
  port->open = false;

  fd = open(devpath, O_RDWR | O_NOCTTY | O_NONBLOCK);
  if (fd < 0)
    {
      return -errno;
    }

  /* Clear O_NONBLOCK for blocking I/O; timeouts via poll. */
  flags = fcntl(fd, F_GETFL, 0);
  if (flags >= 0)
    {
      (void)fcntl(fd, F_SETFL, flags & ~O_NONBLOCK);
    }

  if (tcgetattr(fd, &tio) < 0)
    {
      int err = -errno;
      close(fd);
      return err;
    }

  cfmakeraw(&tio);
  tio.c_cflag |= (CLOCAL | CREAD);
  tio.c_cflag &= ~CRTSCTS;

  tio.c_cflag &= ~CSIZE;
  if (data_bits == 7)
    {
      tio.c_cflag |= CS7;
    }
  else
    {
      tio.c_cflag |= CS8;
    }

  if (stop_bits == 2)
    {
      tio.c_cflag |= CSTOPB;
    }
  else
    {
      tio.c_cflag &= ~CSTOPB;
    }

  if (parity == 'E' || parity == 'e')
    {
      tio.c_cflag |= PARENB;
      tio.c_cflag &= ~PARODD;
    }
  else if (parity == 'O' || parity == 'o')
    {
      tio.c_cflag |= PARENB;
      tio.c_cflag |= PARODD;
    }
  else
    {
      tio.c_cflag &= ~PARENB;
      tio.c_cflag &= ~PARODD;
    }

  if (cfsetspeed(&tio, baud_to_flag(baudrate)) < 0)
    {
      int err = -errno;
      close(fd);
      return err;
    }

  /* Non-canonical: VMIN/VTIME unused; we use poll for timeouts. */
  tio.c_cc[VMIN] = 0;
  tio.c_cc[VTIME] = 0;

  if (tcsetattr(fd, TCSANOW, &tio) < 0)
    {
      int err = -errno;
      close(fd);
      return err;
    }

  (void)tcflush(fd, TCIOFLUSH);

  port->fd = fd;
  port->open = true;
  vg_modbus_port_de_rx(port);

  printf("[VG][MB] serial open %s baud=%d %c%d%d de_gpio=%d\n",
         devpath, baudrate, parity, data_bits, stop_bits, de_gpio);
  return 0;
}

void vg_modbus_port_close(struct vg_modbus_port *port)
{
  if (port == NULL)
    {
      return;
    }

  if (port->fd >= 0)
    {
      close(port->fd);
      port->fd = -1;
    }

  port->open = false;
}

void vg_modbus_port_fill_platform(struct vg_modbus_port *port,
                                  nmbs_platform_conf *conf)
{
  nmbs_platform_conf_create(conf);
  conf->transport = NMBS_TRANSPORT_RTU;
  conf->read = port_read;
  conf->write = port_write;
  conf->arg = port;
}

/****************************************************************************
 * app/velaguard_app/src/vg_modbus_collector.h
 *
 * Dedicated poll task + mutex-protected reading snapshot for UI.
 * Collector never calls LVGL APIs.
 ****************************************************************************/

#ifndef APP_VELAGUARD_APP_SRC_VG_MODBUS_COLLECTOR_H
#define APP_VELAGUARD_APP_SRC_VG_MODBUS_COLLECTOR_H

#include <stdbool.h>
#include <stdint.h>

#include "vg_modbus_profile.h"

enum vg_modbus_quality
{
  VG_MB_Q_UNKNOWN = 0,
  VG_MB_Q_GOOD,
  VG_MB_Q_BAD,
  VG_MB_Q_STALE
};

struct vg_modbus_point_view
{
  char key[VG_MB_KEY_MAX];
  char label[VG_MB_LABEL_MAX];
  char unit[VG_MB_UNIT_MAX];
  float value;
  enum vg_modbus_quality quality;
  uint32_t last_update_ms;
  char last_error[48];
};

struct vg_modbus_snapshot
{
  bool running;
  uint8_t n_points;
  struct vg_modbus_point_view points[VG_MB_MAX_POINTS];
  char test_result[96];
};

/* Call after vg_modbus_profile_load(). Spawns collector pthread. */
int vg_modbus_collector_start(void);

void vg_modbus_snapshot_get(struct vg_modbus_snapshot *out);

/* Async one-shot; result lands in snapshot.test_result. */
void vg_modbus_request_test_read(void);

#endif /* APP_VELAGUARD_APP_SRC_VG_MODBUS_COLLECTOR_H */

/****************************************************************************
 * app/velaguard_app/src/vg_modbus_collector.c
 *
 * Poll loop: nanoMODBUS client over vg_modbus_port, publish snapshot.
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "vg_modbus_collector.h"
#include "vg_modbus_port.h"
#include "vg_modbus_profile.h"
#include "../third_party/nanomodbus/nanomodbus.h"

#define VG_MB_BYTE_TIMEOUT_MS  100
#define VG_MB_RESP_TIMEOUT_MS  500
#define VG_MB_OPEN_RETRY_MS    2000
#define VG_MB_STACK_SIZE       8192

static pthread_mutex_t g_snap_mtx = PTHREAD_MUTEX_INITIALIZER;
static struct vg_modbus_snapshot g_snap;
static volatile bool g_test_req;
static volatile bool g_started;
static pthread_t g_tid;

static uint32_t uptime_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)((uint64_t)ts.tv_sec * 1000ULL +
                    (uint64_t)ts.tv_nsec / 1000000ULL);
}

static void snap_init_from_profile(const struct vg_modbus_profile *p)
{
  uint8_t i;

  pthread_mutex_lock(&g_snap_mtx);
  memset(&g_snap, 0, sizeof(g_snap));
  g_snap.running = false;
  g_snap.n_points = p->n_regs;
  snprintf(g_snap.test_result, sizeof(g_snap.test_result), "idle");

  for (i = 0; i < p->n_regs && i < VG_MB_MAX_POINTS; i++)
    {
      snprintf(g_snap.points[i].key, sizeof(g_snap.points[i].key),
               "%s", p->regs[i].key);
      snprintf(g_snap.points[i].label, sizeof(g_snap.points[i].label),
               "%s", p->regs[i].label);
      snprintf(g_snap.points[i].unit, sizeof(g_snap.points[i].unit),
               "%s", p->regs[i].unit);
      g_snap.points[i].value = 0.0f;
      g_snap.points[i].quality = VG_MB_Q_UNKNOWN;
      g_snap.points[i].last_update_ms = 0;
      g_snap.points[i].last_error[0] = '\0';
    }

  pthread_mutex_unlock(&g_snap_mtx);
}

static void err_str(nmbs_error err, char *buf, size_t buflen)
{
  const char *s;

  switch (err)
    {
      case NMBS_ERROR_NONE:
        s = "ok";
        break;
      case NMBS_ERROR_TIMEOUT:
        s = "timeout";
        break;
      case NMBS_ERROR_CRC:
        s = "crc";
        break;
      case NMBS_ERROR_TRANSPORT:
        s = "io";
        break;
      case NMBS_ERROR_INVALID_RESPONSE:
        s = "bad_resp";
        break;
      case NMBS_ERROR_INVALID_UNIT_ID:
        s = "unit_id";
        break;
      case NMBS_EXCEPTION_ILLEGAL_FUNCTION:
        s = "exc_func";
        break;
      case NMBS_EXCEPTION_ILLEGAL_DATA_ADDRESS:
        s = "exc_addr";
        break;
      case NMBS_EXCEPTION_ILLEGAL_DATA_VALUE:
        s = "exc_value";
        break;
      case NMBS_EXCEPTION_SERVER_DEVICE_FAILURE:
        s = "exc_fail";
        break;
      default:
        s = "error";
        break;
    }

  snprintf(buf, buflen, "%s", s);
}

static uint16_t dtype_qty(enum vg_modbus_dtype dt)
{
  if (dt == VG_MB_DT_UINT32 || dt == VG_MB_DT_INT32)
    {
      return 2;
    }

  return 1;
}

static float decode_value(enum vg_modbus_dtype dt, const uint16_t *regs,
                          float scale, float offset)
{
  float raw = 0.0f;

  switch (dt)
    {
      case VG_MB_DT_INT16:
        raw = (float)(int16_t)regs[0];
        break;
      case VG_MB_DT_UINT32:
        raw = (float)(((uint32_t)regs[0] << 16) | (uint32_t)regs[1]);
        break;
      case VG_MB_DT_INT32:
        raw = (float)(int32_t)(((uint32_t)regs[0] << 16) | (uint32_t)regs[1]);
        break;
      case VG_MB_DT_UINT16:
      default:
        raw = (float)regs[0];
        break;
    }

  return raw * scale + offset;
}

static nmbs_error read_point(nmbs_t *nmbs, const struct vg_modbus_reg *reg,
                             float *value_out)
{
  uint16_t regs[2];
  uint16_t qty = dtype_qty(reg->dtype);
  nmbs_error err;

  memset(regs, 0, sizeof(regs));

  if (reg->function_code == 4)
    {
      err = nmbs_read_input_registers(nmbs, reg->pdu_addr, qty, regs);
    }
  else
    {
      err = nmbs_read_holding_registers(nmbs, reg->pdu_addr, qty, regs);
    }

  if (err == NMBS_ERROR_NONE)
    {
      *value_out = decode_value(reg->dtype, regs, reg->scale, reg->offset);
    }

  return err;
}

static void update_point_ok(uint8_t idx, float value)
{
  pthread_mutex_lock(&g_snap_mtx);
  if (idx < g_snap.n_points)
    {
      g_snap.points[idx].value = value;
      g_snap.points[idx].quality = VG_MB_Q_GOOD;
      g_snap.points[idx].last_update_ms = uptime_ms();
      g_snap.points[idx].last_error[0] = '\0';
    }

  pthread_mutex_unlock(&g_snap_mtx);
}

static void update_point_bad(uint8_t idx, nmbs_error err)
{
  char ebuf[32];

  err_str(err, ebuf, sizeof(ebuf));

  pthread_mutex_lock(&g_snap_mtx);
  if (idx < g_snap.n_points)
    {
      g_snap.points[idx].quality = VG_MB_Q_BAD;
      g_snap.points[idx].last_update_ms = uptime_ms();
      snprintf(g_snap.points[idx].last_error,
               sizeof(g_snap.points[idx].last_error), "%s", ebuf);
    }

  pthread_mutex_unlock(&g_snap_mtx);
}

static void set_test_result(const char *msg)
{
  pthread_mutex_lock(&g_snap_mtx);
  snprintf(g_snap.test_result, sizeof(g_snap.test_result), "%s", msg);
  pthread_mutex_unlock(&g_snap_mtx);

  /* Also append a line to human log when possible. */
  {
    FILE *fp = fopen("/data/velaguard/logs/latest.log", "a");

    if (fp != NULL)
      {
        fprintf(fp, "[MB] test_read: %s\n", msg);
        fclose(fp);
      }
  }

  printf("[VG][MB] test_read: %s\n", msg);
}

static void do_test_read(nmbs_t *nmbs, const struct vg_modbus_profile *p)
{
  float value = 0.0f;
  nmbs_error err;
  char msg[96];

  if (p->n_regs == 0)
    {
      set_test_result("FAIL: no registers");
      return;
    }

  nmbs_set_destination_rtu_address(nmbs, p->slave_addr);
  err = read_point(nmbs, &p->regs[0], &value);
  if (err == NMBS_ERROR_NONE)
    {
      snprintf(msg, sizeof(msg), "OK value=%.3f %s", (double)value,
               p->regs[0].unit);
      update_point_ok(0, value);
    }
  else
    {
      char ebuf[32];

      err_str(err, ebuf, sizeof(ebuf));
      snprintf(msg, sizeof(msg), "FAIL: %s", ebuf);
      update_point_bad(0, err);
    }

  set_test_result(msg);
}

static int ensure_client(struct vg_modbus_port *port, nmbs_t *nmbs,
                         const struct vg_modbus_profile *p, bool *ready)
{
  nmbs_platform_conf conf;
  nmbs_error err;
  int ret;

  if (*ready && port->open)
    {
      return 0;
    }

  ret = vg_modbus_port_open(port, p->port, p->baudrate, p->parity,
                            p->data_bits, p->stop_bits, p->de_gpio);
  if (ret < 0)
    {
      *ready = false;
      return ret;
    }

  vg_modbus_port_fill_platform(port, &conf);
  err = nmbs_client_create(nmbs, &conf);
  if (err != NMBS_ERROR_NONE)
    {
      vg_modbus_port_close(port);
      *ready = false;
      return -EIO;
    }

  nmbs_set_byte_timeout(nmbs, VG_MB_BYTE_TIMEOUT_MS);
  nmbs_set_read_timeout(nmbs, VG_MB_RESP_TIMEOUT_MS);
  nmbs_set_destination_rtu_address(nmbs, p->slave_addr);
  *ready = true;
  return 0;
}

static void mark_all_bad(const char *reason)
{
  uint8_t i;

  pthread_mutex_lock(&g_snap_mtx);
  for (i = 0; i < g_snap.n_points; i++)
    {
      g_snap.points[i].quality = VG_MB_Q_BAD;
      g_snap.points[i].last_update_ms = uptime_ms();
      snprintf(g_snap.points[i].last_error,
               sizeof(g_snap.points[i].last_error), "%s", reason);
    }

  pthread_mutex_unlock(&g_snap_mtx);
}

static FAR void *collector_thread(FAR void *arg)
{
  const struct vg_modbus_profile *p = vg_modbus_profile_get();
  struct vg_modbus_port port;
  nmbs_t nmbs;
  bool ready = false;
  uint32_t interval;

  (void)arg;
  memset(&port, 0, sizeof(port));
  port.fd = -1;
  interval = p->poll_interval_ms;
  if (interval < 500)
    {
      interval = 500;
    }

  if (interval > 5000)
    {
      interval = 5000;
    }

  pthread_mutex_lock(&g_snap_mtx);
  g_snap.running = true;
  pthread_mutex_unlock(&g_snap_mtx);

  printf("[VG][MB] collector started (interval=%ums)\n",
         (unsigned)interval);

  while (1)
    {
      uint32_t t0 = uptime_ms();
      uint8_t i;

      if (g_test_req)
        {
          g_test_req = false;
          if (ensure_client(&port, &nmbs, p, &ready) == 0)
            {
              do_test_read(&nmbs, p);
            }
          else
            {
              set_test_result("FAIL: open");
              mark_all_bad("open");
            }
        }

      if (ensure_client(&port, &nmbs, p, &ready) != 0)
        {
          mark_all_bad("open");
          usleep((useconds_t)VG_MB_OPEN_RETRY_MS * 1000u);
          continue;
        }

      nmbs_set_destination_rtu_address(&nmbs, p->slave_addr);

      for (i = 0; i < p->n_regs && i < VG_MB_MAX_POINTS; i++)
        {
          float value = 0.0f;
          nmbs_error err = read_point(&nmbs, &p->regs[i], &value);

          if (err == NMBS_ERROR_NONE)
            {
              update_point_ok(i, value);
            }
          else
            {
              update_point_bad(i, err);
              if (err == NMBS_ERROR_TRANSPORT)
                {
                  vg_modbus_port_close(&port);
                  ready = false;
                  break;
                }
            }
        }

      {
        uint32_t elapsed = uptime_ms() - t0;

        if (elapsed < interval)
          {
            usleep((useconds_t)(interval - elapsed) * 1000u);
          }
      }
    }

  return NULL;
}

int vg_modbus_collector_start(void)
{
  pthread_attr_t attr;
  int ret;
  const struct vg_modbus_profile *p = vg_modbus_profile_get();

  if (g_started)
    {
      return 0;
    }

  snap_init_from_profile(p);

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, VG_MB_STACK_SIZE);

  ret = pthread_create(&g_tid, &attr, collector_thread, NULL);
  pthread_attr_destroy(&attr);

  if (ret != 0)
    {
      printf("[VG][MB] ERROR: collector pthread_create failed: %d\n", ret);
      return -ret;
    }

  pthread_detach(g_tid);
  g_started = true;
  printf("[VG][MB] collector task created\n");
  return 0;
}

void vg_modbus_snapshot_get(struct vg_modbus_snapshot *out)
{
  if (out == NULL)
    {
      return;
    }

  pthread_mutex_lock(&g_snap_mtx);
  *out = g_snap;
  pthread_mutex_unlock(&g_snap_mtx);
}

void vg_modbus_request_test_read(void)
{
  g_test_req = true;
  pthread_mutex_lock(&g_snap_mtx);
  snprintf(g_snap.test_result, sizeof(g_snap.test_result), "pending...");
  pthread_mutex_unlock(&g_snap_mtx);
}

/****************************************************************************
 * app/velaguard_app/src/vg_ui_home.c
 *
 * Issue #01 home UI + Issue #02 live ACQUIRE / detail / Test Read.
 * Design tokens: Dark OLED ops (bg #0F172A, surface #1E293B, accent #22C55E).
 * Identity is display-only. Collector never called from LVGL thread for I/O;
 * UI only reads vg_modbus_snapshot via timer.
 ****************************************************************************/

