void vg_ui_home_create(void)
{
  lv_obj_t *scr = lv_screen_active();

  lv_obj_set_style_bg_color(scr, C_BG, 0);
  lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
  lv_obj_clear_flag(scr, LV_OBJ_FLAG_SCROLLABLE);

  make_header(scr);
  make_identity(scr);
  make_kpi_row(scr);

#ifdef CONFIG_VG_ENABLE_MODBUS
  make_detail_panel(scr);
  lv_timer_create(refresh_modbus_ui, 300, NULL);
#endif
}

/****************************************************************************
 * app/velaguard_app/velaguard_main.c
 *
 * VelaGuard boot entry. Boot order:
 *   device id -> data dir -> startup log/event
 *   -> [#02] modbus profile + collector
 *   -> LVGL -> home UI -> loop
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <unistd.h>
#include <sys/boardctl.h>

#include <lvgl/lvgl.h>

#include "src/vg_device_id.h"
#include "src/vg_log.h"
#include "src/vg_ui_home.h"

#ifdef CONFIG_VG_ENABLE_MODBUS
#  include "src/vg_modbus_profile.h"
#  include "src/vg_modbus_collector.h"
#endif

#define VG_INPUT_DEVPATH "/dev/input0"

#undef NEED_BOARDINIT
#if defined(CONFIG_BOARDCTL) && !defined(CONFIG_NSH_ARCHINIT)
#  define NEED_BOARDINIT 1
#endif

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;
  int ret;

  (void)argc;
  (void)argv;

  printf("===========================================\n");
  printf("  VelaGuard - Industrial Edge AI Gateway\n");
  printf("===========================================\n");

  vg_device_id_init();
  printf("[VG] Device ID: %s\n", vg_get_device_id());
  printf("[VG] Build mode: %s\n", vg_build_mode_str());

  ret = vg_log_init();
  if (ret < 0)
    {
      fprintf(stderr, "[VG] WARNING: Data directory init failed: %d\n", ret);
    }

  ret = vg_log_startup_event();
  if (ret < 0)
    {
      fprintf(stderr, "[VG] WARNING: Startup event log failed: %d\n", ret);
    }

#ifdef CONFIG_VG_ENABLE_MODBUS
  /* After log init so /data/velaguard/configs exists for optional JSON.
   * USART3/PB10-PB11 becomes Modbus at profile baud after collector starts;
   * VCP console is unavailable while RS485 is active on the same pins.
   */
  ret = vg_modbus_profile_load();
  if (ret < 0)
    {
      fprintf(stderr, "[VG] WARNING: Modbus profile load failed: %d\n", ret);
    }

  ret = vg_modbus_collector_start();
  if (ret < 0)
    {
      fprintf(stderr, "[VG] WARNING: Modbus collector start failed: %d\n", ret);
    }
#endif

  if (lv_is_initialized())
    {
      fprintf(stderr, "[VG] ERROR: LVGL already initialized\n");
      return -1;
    }

#ifdef NEED_BOARDINIT
  boardctl(BOARDIOC_INIT, 0);
#endif

  lv_init();
  lv_nuttx_dsc_init(&info);

#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif

#ifdef CONFIG_INPUT_TOUCHSCREEN
  info.input_path = VG_INPUT_DEVPATH;
#endif

  lv_nuttx_init(&info, &result);
  if (result.disp == NULL)
    {
      fprintf(stderr, "[VG] ERROR: LVGL display init failed\n");
      lv_deinit();
      return 1;
    }

  printf("[VG] LVGL display initialized\n");
  vg_ui_home_create();
  printf("[VG] Home screen created\n");
  printf("[VG] Entering event loop\n");

  while (1)
    {
      uint32_t idle = lv_timer_handler();

      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }

  lv_nuttx_deinit(&result);
  lv_deinit();
  return 0;
}

